SELECT gen_random_uuid()::text, 'formula', '$\frac{R_2}{R_1} = \frac{234.5 + T_2}{234.5 + T_1}$', 'Inferred Absolute Zero of Copper', '$\frac{R_2}{R_1} = \frac{T + T_2}{T + T_1};\qquad T = 234.5\,^\circ\text{C (copper)},\ 228\,^\circ\text{C (aluminium)}$', NULL, 'Resistance at a new temperature using the temperature at which the metal''s resistance would extrapolate to zero.', '[{"symbol":"$R_1, R_2$","meaning":"resistances at temperatures T₁ and T₂","unit":"$\\Omega$"},{"symbol":"$T_1, T_2$","meaning":"temperatures","unit":"$^\\circ\\text{C}$"}]'::jsonb, 'It gives α at 20 °C for copper: 1/(234.5 + 20) = 0.00393 per °C.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'dc and ac sources and components' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
