SELECT gen_random_uuid()::text, 'formula', '$R_s = \sum R,\ \frac{1}{R_p} = \sum\frac{1}{R}$', 'Resistors in Series and Parallel', '$R_s = R_1 + R_2 + \cdots;\qquad \frac{1}{R_p} = \frac{1}{R_1} + \frac{1}{R_2} + \cdots;\qquad \text{two: } R_p = \frac{R_1R_2}{R_1 + R_2}$', '$\Omega$', 'Combining resistors: series add, parallel add as conductances.', '[{"symbol":"$R_k$","meaning":"resistances","unit":"$\\Omega$"}]'::jsonb, 'A parallel combination is always smaller than its smallest resistor. n equal resistors: R/n.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'dc and ac sources and components' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
