SELECT gen_random_uuid()::text, 'formula', '$\sum i = 0,\ \sum v = 0$', 'Kirchhoff''s Current and Voltage Laws', '$\text{KCL: } \sum i_{\text{into node}} = 0;\qquad \text{KVL: } \sum v_{\text{around loop}} = 0$', NULL, 'Charge is conserved at every node, and energy around every closed loop.', '[{"symbol":"$i$","meaning":"branch currents","unit":"$\\text{A}$"},{"symbol":"$v$","meaning":"element voltages","unit":"$\\text{V}$"}]'::jsonb, 'Pick one sign convention and keep it: a voltage rise counts the opposite way to a drop.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'voltage and current laws' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
