SELECT gen_random_uuid()::text, 'formula', '$\mathbf{G}\mathbf{v} = \mathbf{i}$', 'Nodal Analysis (Conductance Matrix)', '$\mathbf{G}\mathbf{v} = \mathbf{i};\qquad G_{kk} = \sum \text{conductances at node } k,\quad G_{kj} = -\text{conductance between } k \text{ and } j$', NULL, 'Node voltages from KCL at every node but the reference, written as a matrix.', '[{"symbol":"$\\mathbf{v}$","meaning":"node voltages from the reference","unit":"$\\text{V}$"},{"symbol":"$\\mathbf{i}$","meaning":"source currents into each node","unit":"$\\text{A}$"}]'::jsonb, 'A voltage source between two non-reference nodes makes a supernode: write KCL around both together.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'nodal analysis' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
