SELECT gen_random_uuid()::text, 'formula', '$\mathbf{R}\mathbf{i} = \mathbf{v}$', 'Mesh Analysis (Resistance Matrix)', '$\mathbf{R}\mathbf{i} = \mathbf{v};\qquad R_{kk} = \sum \text{resistance around mesh } k,\quad R_{kj} = -\text{resistance shared by } k \text{ and } j$', NULL, 'Mesh currents from KVL around every window of a planar circuit.', '[{"symbol":"$\\mathbf{i}$","meaning":"mesh currents, all clockwise","unit":"$\\text{A}$"},{"symbol":"$\\mathbf{v}$","meaning":"source voltages driving each mesh","unit":"$\\text{V}$"}]'::jsonb, 'A current source shared by two meshes makes a supermesh. A shared resistor carries the DIFFERENCE of the two mesh currents.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'mesh analysis' AND s."active"), NULL, true, 'PENDING', now(), now()
