SELECT gen_random_uuid()::text, 'formula', '$V_s = I_sR$', 'Source Transformation', '$V_s = I_sR \iff I_s = \frac{V_s}{R}\quad (\text{same } R \text{ in series or in parallel})$', NULL, 'A voltage source with series R is equivalent, at its terminals, to a current source with the same R in parallel.', '[{"symbol":"$V_s$","meaning":"voltage source","unit":"$\\text{V}$"},{"symbol":"$I_s$","meaning":"current source","unit":"$\\text{A}$"},{"symbol":"$R$","meaning":"its resistance","unit":"$\\Omega$"}]'::jsonb, 'The current source points toward the + terminal of the voltage source it replaces.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'source transformation' AND s."active"), NULL, true, 'PENDING', now(), now()
