SELECT gen_random_uuid()::text, 'formula', '$R_{th} = \frac{V_{oc}}{I_{sc}}$', 'Thevenin and Norton Equivalents', '$V_{th} = V_{oc},\qquad I_N = I_{sc},\qquad R_{th} = R_N = \frac{V_{oc}}{I_{sc}}$', '$\Omega$', 'Any linear two-terminal circuit is a source and one resistance.', '[{"symbol":"$V_{oc}$","meaning":"open-circuit voltage at the terminals","unit":"$\\text{V}$"},{"symbol":"$I_{sc}$","meaning":"short-circuit current","unit":"$\\text{A}$"}]'::jsonb, 'With only independent sources, R_th is the resistance seen with them turned off. With dependent sources, use V_oc/I_sc or a test source.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'thevenin and norton' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
