SELECT gen_random_uuid()::text, 'formula', '$P_L = \frac{V_{th}^2R_L}{(R_{th} + R_L)^2}$', 'Load Power versus Load Resistance', '$P_L = \frac{V_{th}^2R_L}{(R_{th} + R_L)^2},\qquad \eta = \frac{R_L}{R_{th} + R_L}$', '$\text{W}$', 'The power a load gets from a Thévenin source, and the efficiency of the transfer.', '[{"symbol":"$V_{th}, R_{th}$","meaning":"Thévenin source","unit":"$\\text{V}$"},{"symbol":"$R_L$","meaning":"load","unit":"$\\Omega$"}]'::jsonb, 'Power peaks at R_L = R_th (η = 50%); power systems instead run R_L ≫ R_th for high efficiency.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'maximum power transfer' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
