SELECT gen_random_uuid()::text, 'formula', '$R_a = \frac{R_{ab}R_{ca}}{R_{ab} + R_{bc} + R_{ca}}$', 'Delta-Wye Conversion', '$\Delta \to Y: R_a = \frac{R_{ab}R_{ca}}{\Sigma R_\Delta};\qquad Y \to \Delta: R_{ab} = \frac{R_aR_b + R_bR_c + R_cR_a}{R_c};\qquad \text{balanced: } R_Y = \frac{R_\Delta}{3}$', '$\Omega$', 'Converting between a triangle and a star of three resistors so a bridge can be reduced.', '[{"symbol":"$R_{ab}, R_{bc}, R_{ca}$","meaning":"delta resistances","unit":"$\\Omega$"},{"symbol":"$R_a, R_b, R_c$","meaning":"wye resistances","unit":"$\\Omega$"}]'::jsonb, 'Δ→Y: the two delta resistors touching the node, over the sum. Y→Δ: sum of products, over the opposite wye resistor.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'delta-wye conversion' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
