SELECT gen_random_uuid()::text, 'formula', '$v_+ = v_-,\ i_\pm = 0$', 'Ideal Op-Amp Rules', '$v_+ = v_-\ (\text{with negative feedback}),\qquad i_+ = i_- = 0;\qquad \text{follower: } v_o = v_{in}$', NULL, 'The two rules that solve every ideal op-amp circuit: the inputs sit at the same voltage, and draw no current.', '[{"symbol":"$v_+, v_-$","meaning":"input terminal voltages","unit":"$\\text{V}$"},{"symbol":"$i_+, i_-$","meaning":"input currents","unit":"$\\text{A}$"}]'::jsonb, 'The output can''t exceed the supply rails: past them it saturates. Inverting and non-inverting gains are in Electronics.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'controlled sources and ideal op amp' AND s."active"), NULL, true, 'PENDING', now(), now()
