SELECT gen_random_uuid()::text, 'formula', '$v_o = -R_f\sum\frac{v_k}{R_k}$', 'Summing Amplifier', '$v_o = -R_f\left(\frac{v_1}{R_1} + \frac{v_2}{R_2} + \cdots\right)$', '$\text{V}$', 'An inverting amplifier with several inputs: a weighted sum.', '[{"symbol":"$R_f$","meaning":"feedback resistor","unit":"$\\Omega$"},{"symbol":"$v_k, R_k$","meaning":"each input and its resistor","unit":"$\\text{V}$"}]'::jsonb, 'With all resistors equal it adds the inputs (inverted); a DAC is a summer with binary-weighted resistors.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'controlled sources and ideal op amp' AND s."active"), NULL, false, 'PENDING', now(), now()
