SELECT gen_random_uuid()::text, 'formula', '$v_o = \frac{R_2}{R_1}(v_2 - v_1)$', 'Difference Amplifier', '$v_o = \frac{R_2}{R_1}(v_2 - v_1)\quad (\text{matched ratios } R_4/R_3 = R_2/R_1)$', '$\text{V}$', 'Amplifies the difference between two inputs and rejects what they have in common.', '[{"symbol":"$v_1, v_2$","meaning":"inverting and non-inverting inputs","unit":"$\\text{V}$"},{"symbol":"$R_1, R_2$","meaning":"input and feedback resistors","unit":"$\\Omega$"}]'::jsonb, 'Unmatched ratios let common-mode voltage leak through: why instrumentation amplifiers exist.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'controlled sources and ideal op amp' AND s."active"), NULL, false, 'PENDING', now(), now()
