SELECT gen_random_uuid()::text, 'formula', '$i = C\frac{dv}{dt},\ v = L\frac{di}{dt}$', 'Capacitor and Inductor Laws', '$i_C = C\frac{dv_C}{dt},\qquad v_L = L\frac{di_L}{dt}$', NULL, 'How capacitors and inductors relate current and voltage.', '[{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"}]'::jsonb, 'A capacitor''s voltage and an inductor''s current can''t jump. In dc steady state a capacitor is open, an inductor shorted.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'capacitors and inductors' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
