SELECT gen_random_uuid()::text, 'formula', '$C_p = \sum C,\ L_s = \sum L$', 'Capacitance and Inductance Combinations', '$C_p = \sum C_k,\ \frac{1}{C_s} = \sum\frac{1}{C_k};\qquad L_s = \sum L_k,\ \frac{1}{L_p} = \sum\frac{1}{L_k}$', NULL, 'Combining capacitors (opposite to resistors) and inductors (like resistors).', '[{"symbol":"$C_k$","meaning":"capacitances","unit":"$\\text{F}$"},{"symbol":"$L_k$","meaning":"inductances (no mutual coupling)","unit":"$\\text{H}$"}]'::jsonb, 'Series capacitors share the same charge; their voltages divide inversely to C.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'capacitors and inductors' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
