SELECT gen_random_uuid()::text, 'formula', '$x(t) = x_\infty + (x_0 - x_\infty)e^{-t/\tau}$', 'First-Order Step Response', '$x(t) = x(\infty) + [x(0^+) - x(\infty)]e^{-t/\tau};\qquad \tau = RC \text{ or } \frac{L}{R}$', NULL, 'Every RC or RL circuit with a step input: start value, final value and time constant are all you need.', '[{"symbol":"$x$","meaning":"any voltage or current in the circuit","unit":null},{"symbol":"$\\tau$","meaning":"time constant (R is the Thévenin resistance seen by C or L)","unit":"$\\text{s}$"}]'::jsonb, 'After 5τ the response is within 1% of final. Find x(0⁺) from the capacitor voltage or inductor current, which don''t jump.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'rl and rc circuits' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
