SELECT gen_random_uuid()::text, 'formula', '$s = -\alpha \pm \sqrt{\alpha^2 - \omega_0^2}$', 'RLC Characteristic Roots', '$s_{1,2} = -\alpha \pm \sqrt{\alpha^2 - \omega_0^2};\quad \omega_0 = \frac{1}{\sqrt{LC}};\quad \alpha = \frac{R}{2L}\ (\text{series}),\ \frac{1}{2RC}\ (\text{parallel})$', '$\text{1/s}$', 'The natural response of an RLC circuit: overdamped (α > ω₀), critically damped (=), or underdamped (<) and ringing.', '[{"symbol":"$\\alpha$","meaning":"neper frequency","unit":"$\\text{Np/s}$"},{"symbol":"$\\omega_0$","meaning":"resonant frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'Series and parallel have different α: R raises the series damping but LOWERS the parallel damping.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'rlc circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
