SELECT gen_random_uuid()::text, 'formula', '$\mathbf{V} = V_m\angle\phi$', 'Phasor Representation', '$v(t) = V_m\cos(\omega t + \phi) \iff \mathbf{V} = V_m\angle\phi = V_m(\cos\phi + j\sin\phi)$', NULL, 'A sinusoid of known frequency as a complex number: calculus becomes algebra.', '[{"symbol":"$V_m$","meaning":"amplitude","unit":"$\\text{V}$"},{"symbol":"$\\phi$","meaning":"phase angle","unit":null},{"symbol":"$\\omega$","meaning":"angular frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'Use the same reference (cosine or sine) for every source. Board answers usually use RMS phasors: V_m/√2.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'phasors and impedance' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
