SELECT gen_random_uuid()::text, 'formula', '$Z = R + jX$', 'Impedance and Admittance', '$Z_R = R,\ Z_L = j\omega L,\ Z_C = \frac{1}{j\omega C};\qquad Z = R + jX,\qquad Y = \frac{1}{Z} = G + jB$', '$\Omega$', 'The ac version of resistance, a complex number, and its reciprocal.', '[{"symbol":"$R$","meaning":"resistance","unit":"$\\Omega$"},{"symbol":"$X$","meaning":"reactance (+ inductive, − capacitive)","unit":"$\\Omega$"},{"symbol":"$G, B$","meaning":"conductance and susceptance","unit":"$\\text{S}$"}]'::jsonb, 'G is not 1/R unless X = 0: G = R/(R² + X²).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'phasors and impedance' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
