SELECT gen_random_uuid()::text, 'formula', '$Z_s = \sum Z,\ \frac{1}{Z_p} = \sum\frac{1}{Z}$', 'Impedances in Series and Parallel', '$\mathbf{V} = \mathbf{I}Z;\qquad Z_s = \sum Z_k;\qquad \frac{1}{Z_p} = \sum\frac{1}{Z_k};\qquad |Z| = \sqrt{R^2 + X^2},\ \theta = \tan^{-1}\frac{X}{R}$', '$\Omega$', 'Ohm''s law and the series-parallel rules carried over to ac with complex impedances: every dc method (nodal, mesh, Thévenin) works the same way.', '[{"symbol":"$Z_k$","meaning":"impedances","unit":"$\\Omega$"}]'::jsonb, 'Add impedances as complex numbers, never their magnitudes: 3 Ω + j4 Ω is 5 Ω, not 7.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE' AND s."normKey" = 'sinusoidal steady-state analysis' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 1' AND t."subject" = 'EE'
